            state["progress_counter"] += 1
        else:
            state["progress_counter"] = 0

        if state["progress_counter"] >= 5:
            state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        fx = 0.0
        fy = w_comp

    sandbox.apply_agent_force(fx, fy)

import math

ACTIVATION_X_MIN = 5.0
ACTIVATION_X_MAX = 10.0
UNLOCK_FORCE = -35.0
ESCAPE_FORCE = 120.0
MIN_WALL_CLEARANCE = 0.5
TARGET_Y = 1.5
MAX_STAGNATION_STEPS = 5
BURST_FORCE_MIN = 90.0
BURST_FORCE_MAX = 120.0
BURST_INCREMENT = 10.0
PROGRESS_THRESHOLD = 0.1
EXIT_X_MIN = 15.0

class Memory:
    def __init__(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return 5.0 * abs(gy)  # Assuming agent mass is 5.0

def build_agent(sandbox):
    MEM.data.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "state" not in MEM.data:
        MEM.data["state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "stagnation_counter": 0,
            "burst_force": BURST_FORCE_MIN,
        }
    state = MEM.data["state"]
    pd = sandbox.get_agent_position()
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / (1.0 / 60.0)
        state["vy"] = (pd[1] - state["ly"]) / (1.0 / 60.0)
    state["lx"], state["ly"] = pd[0], pd[1]
    x, y = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]

    front, up, down = sandbox.get_whisker_readings()
    w_comp = _weight_comp(sandbox)

    if state["phase"] == "APPROACH":
        if x < 5.0:
            fx = 40.0 - 0.5 * vxd
        else:
            fx = 10.0 * (7.0 - x) - 5.0 * vxd

        desired_y = TARGET_Y
        # Adjust y to avoid floor/ceiling
        if down < MIN_WALL_CLEARANCE:
            desired_y = y + 0.1
        elif up < MIN_WALL_CLEARANCE:
            desired_y = y - 0.1

        # Use vertical whiskers to adjust y if forward is blind
        if front == 3.0 and up > down:
            desired_y = y + 0.1
        elif front == 3.0 and down > up:
            desired_y = y - 0.1
        desired_y = max(0.5, min(2.5, desired_y))

        fy = 50.0 * (desired_y - y) - 20.0 * vyd + w_comp

        # Transition to UNLOCK if in activation zone and at low speed
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0

    elif state["phase"] == "UNLOCK":
        fx = UNLOCK_FORCE
        fy = 50.0 * (TARGET_Y - y) - 20.0 * vyd + w_comp
        state["t"] += 1
        if state["t"] >= 5:
            state["phase"] = "ESCAPE"

    elif state["phase"] == "ESCAPE":
        # Use vertical proximity to adjust y to avoid walls
        desired_y = TARGET_Y
        if up < MIN_WALL_CLEARANCE:
            desired_y = y - 0.1  # move down if near top of wall
        if down < MIN_WALL_CLEARANCE:
            desired_y = y + 0.1  # move up if near bottom of wall

        # Special adjustment to avoid internal wall at y=0.0-2.0
        if 8.5 <= x <= 10.0 and y < 2.0:
            desired_y = y + 0.1

        desired_y = max(0.5, min(2.5, desired_y))
        fy = 50.0 * (desired_y - y) - 20.0 * vyd + w_comp

        # Apply high forward force unless near wall (detected via vertical proximity)
        if up < MIN_WALL_CLEARANCE or down < MIN_WALL_CLEARANCE:
            fx = 30.0  # reduce force to avoid collision
        else:
            fx = ESCAPE_FORCE

        # Stagnation detection and burst force
        if abs(vxd) < PROGRESS_THRESHOLD:
            state["stagnation_counter"] += 1
        else:
            state["stagnation_counter"] = 0

        if state["stagnation_counter"] >= MAX_STAGNATION_STEPS:
            fx = state["burst_force"]
            state["burst_force"] = min(BURST_FORCE_MAX, state["burst_force"] + BURST_INCREMENT)
            state["stagnation_counter"] = 0
        else:
            state["burst_force"] = BURST_FORCE_MIN

        # Continue until exit is reached
        if x >= EXIT_X_MIN:
            state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        fx = 0.0
        fy = w_comp

    sandbox.apply_agent_force(fx, fy)
